"""Build the adjacent Lumen client on Windows, without bundling user state."""
import argparse,ast,base64,hashlib,json,os,platform,shutil,subprocess,sys,tempfile,types
from pathlib import Path

MODULES=('app','core','widgets','profiles','pairing','local_location','windows_engine',
         'preferences','hardware','native_transport','transport','theme','themes','icons')
HELPERS=('watchdog','console_break')
BINARIES=('sing-box.exe','wintun.dll','lumen-transport.exe')
ASSET_FILES=('countries.json','world.geojson','ip-country.sqlite','lumen.png','lumen.ico','lumen.svg','map.path','dns-ca.pem','root-trust-anchor.key')

# User-supplied Lumen shield icon; no source-image metadata is copied.
APP_ICON = ''

class Helpers(ast.NodeTransformer):
    """Only change the known Python helper subprocess command prefixes."""
    def __init__(self):self.changed=0
    def visit_List(self,node):
        self.generic_visit(node)
        if len(node.elts)>=2 and ast.unparse(node.elts[0]) in ('sys.executable','os.sys.executable'):
            text=ast.unparse(node.elts[1])
            for name in HELPERS:
                if name+'.py' in text:
                    node.elts[1:2]=[ast.Constant('--lumen-helper'),ast.Constant(name)]
                    self.changed+=1
                    break
        return node

def stage_client(root,stage):
    stage.mkdir(parents=True)
    for required in ('app.py','app.pyw','core.py','windows_engine.py','requirements.txt','engine-manifest.json'):
        if not (root/required).is_file():raise RuntimeError('Missing client file: '+required)
    names=set(MODULES)
    pending=list(MODULES)
    while pending:
        module=pending.pop();source=root/(module+'.py')
        if not source.is_file():continue
        for node in ast.walk(ast.parse(source.read_text(encoding='utf-8-sig'))):
            imported=[a.name.split('.')[0] for a in node.names] if isinstance(node,ast.Import) else ([node.module.split('.')[0]] if isinstance(node,ast.ImportFrom) and node.module else [])
            for name in imported:
                if name not in names and (root/(name+'.py')).is_file():names.add(name);pending.append(name)
    for name in sorted(names):
        src=root/(name+'.py')
        if src.is_file():shutil.copyfile(src,stage/src.name)
    for name in HELPERS:
        src=root/(name+'.py')
        if src.is_file():shutil.copyfile(src,stage/src.name)
    patch=Helpers();engine=stage/'windows_engine.py'
    tree=patch.visit(ast.parse(engine.read_text(encoding='utf-8-sig')))
    engine.write_text(ast.unparse(ast.fix_missing_locations(tree))+'\n',encoding='utf-8')
    if patch.changed!=2:raise RuntimeError('Unrecognized Windows helper launch code. This client needs a build-kit update.')
    for module in names:
        if module=='windows_engine':continue
        staged=stage/(module+'.py')
        if staged.is_file():
            transform=Helpers();tree=transform.visit(ast.parse(staged.read_text(encoding='utf-8-sig')))
            if transform.changed:staged.write_text(ast.unparse(ast.fix_missing_locations(tree))+'\n',encoding='utf-8')
    shutil.copyfile(root/'frozen_entry.py',stage/'frozen_entry.py')
    for name in ('engine-manifest.json','DOCUMENTATION.md'):
        if (root/name).is_file():shutil.copyfile(root/name,stage/name)
    (stage/'assets').mkdir()
    for name in ASSET_FILES:
        src=root/'assets'/name
        if src.is_file():shutil.copyfile(src,stage/'assets'/name)
    for folder in ('flags','icons'):
        for src in (root/'assets'/folder).glob('*.svg'):
            target=stage/'assets'/folder/src.name;target.parent.mkdir(exist_ok=True);shutil.copyfile(src,target)
    (stage/'bin').mkdir()
    manifest=json.loads((root/'engine-manifest.json').read_text(encoding='utf-8-sig'))
    for name,key in [('sing-box.exe','engine_sha256'),('wintun.dll','wintun_sha256'),('lumen-transport.exe','transport_sha256')]:
        src=root/'bin'/name
        if key not in manifest:
            if name=='lumen-transport.exe':continue
            raise RuntimeError('Missing integrity hash: '+key)
        if not src.is_file() or hashlib.sha256(src.read_bytes()).hexdigest()!=manifest[key]:raise RuntimeError('Missing or damaged networking component: '+name)
        shutil.copyfile(src,stage/'bin'/name)
    if 'dns_sha256' in manifest:
        for name,key in [('dns-ca.pem','dns_ca_sha256'),('root-trust-anchor.key','dns_anchor_sha256')]:
            if hashlib.sha256((root/'assets'/name).read_bytes()).hexdigest()!=manifest[key]:raise RuntimeError('Missing or damaged DNS trust data: '+name)
        source=root/'bin/unbound/unbound.exe'
        if not source.is_file() or hashlib.sha256(source.read_bytes()).hexdigest()!=manifest['dns_sha256']:raise RuntimeError('Missing or damaged DNS validator')
        (stage/'bin/unbound').mkdir();shutil.copyfile(source,stage/'bin/unbound/unbound.exe')
    # Preserve redistribution notices and required third-party source; exclude build tools/state.
    legal=stage/'third-party';legal.mkdir()
    for src in (root/'bin').glob('*LICENSE*.txt'):shutil.copyfile(src,legal/src.name)
    for src in (root/'third-party').rglob('*'):
        if src.is_file() and src.suffix.lower() in ('.txt','.md','.gz','.xz','.zip','.patch'):
            dst=legal/src.relative_to(root/'third-party');dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dst)
    return stage

def make_spec(stage):
    # Source paths stay in temporary build files, never in release manifests.
    datas=[(str(stage/'assets'),'assets'),(str(stage/'engine-manifest.json'),'.'),(str(stage/'third-party'),'third-party')]
    for name in ('DOCUMENTATION.md',*(h+'.py' for h in HELPERS)):
        if (stage/name).exists():datas.append((str(stage/name),'.'))
    binaries=[(str(p),p.parent.relative_to(stage).as_posix()) for p in (stage/'bin').rglob('*') if p.is_file()]
    text="a=Analysis(['frozen_entry.py'], pathex=[], binaries="+repr(binaries)+", datas="+repr(datas)+", hiddenimports=['keyring.backends.Windows'], excludes=['tkinter','PySide6.QtQml','PySide6.QtQuick','PySide6.QtNetwork','PySide6.QtTest'], noarchive=False)\npyz=PYZ(a.pure)\n"
    icon=stage/'assets/lumen.ico'
    opts="name='Lumen VPN', console=False, debug=False, strip=False, upx=False, uac_admin=True, icon="+repr(str(icon) if icon.is_file() else None)
    text+='exe=EXE(pyz,a.scripts,a.binaries,a.datas,[], '+opts+')\n'
    return text

def publish(exe,root):
    destination=root/'Lumen VPN.exe'
    handle,name=tempfile.mkstemp(prefix='.lumen-output-',suffix='.tmp',dir=root)
    os.close(handle);pending=Path(name)
    try:
        shutil.copyfile(exe,pending)
        os.replace(pending,destination)
    finally:pending.unlink(missing_ok=True)
    return destination

def code_paths(code):
    if isinstance(code,types.CodeType):
        yield code.co_filename
        for constant in code.co_consts:yield from code_paths(constant)

def audit(exe,private_markers,temp):
    """Inspect compressed Python archives as well as ordinary binary strings."""
    import marshal
    from PyInstaller.archive.readers import CArchiveReader,ZlibArchiveReader
    def scan(raw):
        raw=raw.lower()
        for marker in private_markers:
            for encoding in ('utf-8','utf-16-le'):
                if marker.lower().encode(encoding) in raw:raise RuntimeError('A local build identifier was found; release blocked.')
    def check_path(code):
        for name in code_paths(code):
            if Path(name).is_absolute() or ':\\' in name or ':/' in name:
                raise RuntimeError('Absolute Python source path in executable; release blocked.')
        def check_constants(value):
            if isinstance(value,types.CodeType):
                for c in value.co_consts:check_constants(c)
            elif isinstance(value,str):scan(value.encode('utf-8'))
            elif isinstance(value,bytes):scan(value)
            elif isinstance(value,(tuple,frozenset)):
                for c in value:check_constants(c)
        check_constants(code)
    archive=CArchiveReader(str(exe))
    for name,entry in archive.toc.items():
        scan(archive.extract(name))
        if entry[-1] in ('s','m','M'):check_path(marshal.loads(archive.extract(name)))
        if entry[-1]=='z':
            pyz=temp/'audit.pyz';pyz.write_bytes(archive.extract(name));reader=ZlibArchiveReader(str(pyz))
            for module in reader.toc:check_path(reader.extract(module))
    for p in exe.parent.rglob('*'):
        if p.is_file():
            scan(p.read_bytes())

def main():
    argparse.ArgumentParser(description='Build Lumen VPN.exe beside app.pyw; temporary files are cleaned up.').parse_args()
    if os.name!='nt' or platform.machine().lower() not in ('amd64','x86_64') or sys.maxsize<=2**32:raise RuntimeError('Build on Windows x64 using 64-bit Python.')
    root=Path(__file__).resolve().parent
    # Temporary dependency target keeps unrelated global packages out of analysis.
    with tempfile.TemporaryDirectory(prefix='lumen-build-') as work:
        work=Path(work);stage=stage_client(root,work/'src');deps=work/'packages';deps.mkdir()
        env=os.environ.copy();env['PYTHONNOUSERSITE']='1';env['PIP_CONFIG_FILE']=os.devnull;env.pop('PYTHONPATH',None)
        print('Installing build dependencies into a temporary folder (no virtual environment).',flush=True)
        subprocess.run([sys.executable,'-m','pip','--isolated','install','--no-compile','--only-binary=:all:','--target',str(deps),'PyInstaller==6.22.3','-r',str(root/'requirements.txt')],env=env,check=True)
        # Always use the selected icon, including when an old client icon exists.
        (stage/'assets/lumen.ico').write_bytes(base64.b64decode(APP_ICON))
        # Embed dependency notices rather than leaving loose legal files.
        for package in deps.glob('*.dist-info'):
            for src in package.rglob('*'):
                if src.is_file() and ('license' in src.name.lower() or 'notice' in src.name.lower() or 'licenses' in src.parts):
                    dst=stage/'third-party/dependencies'/package.name/src.relative_to(package)
                    dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dst)
        spec=stage/'Lumen.spec';spec.write_text(make_spec(stage),encoding='utf-8')
        runner=work/'runner.py';runner.write_text('import sys\nsys.path.insert(0,'+repr(str(deps))+')\nimport PyInstaller.__main__\nPyInstaller.__main__.run(sys.argv[1:])\n',encoding='utf-8')
        print('Building Lumen VPN (no UPX, no obfuscation).',flush=True)
        subprocess.run([sys.executable,'-S',str(runner),'--clean','--noconfirm','--distpath',str(work/'dist'),'--workpath',str(work/'build'),str(spec)],cwd=stage,env=env,check=True)
        sys.path.insert(0,str(deps))
        exe=work/'dist/Lumen VPN.exe'
        markers=[str(root),str(work),str(Path.home())]
        computer=os.environ.get('COMPUTERNAME','')
        if len(computer)>=5:markers.append(computer)
        audit(exe,markers,work)
        destination=publish(exe,root)
        print('Finished: '+str(destination),flush=True)

if __name__=='__main__':
    try:main()
    except Exception as error:
        print('Build failed: '+str(error),file=sys.stderr);raise SystemExit(1)
